import{_ as e,c as t,o as r,ah as o}from"./chunks/framework.Ch_PcVtW.js";const u=JSON.parse('{"title":"VitePress","description":"","frontmatter":{"title":"VitePress"},"headers":[],"relativePath":"scripts/output/0_INTRO/4_human_proofed.md","filePath":"scripts/output/0_INTRO/4_human_proofed.md"}'),p={name:"scripts/output/0_INTRO/4_human_proofed.md"};function s(_,a,n,i,c,T){return r(),t("div",null,[...a[0]||(a[0]=[o('<h2 id="持续进化的每一天的底层是各自铭记的信念——" tabindex="-1">持续进化的每一天的底层是各自铭记的信念—— <a class="header-anchor" href="#持续进化的每一天的底层是各自铭记的信念——" aria-label="Permalink to &quot;持续进化的每一天的底层是各自铭记的信念——&quot;">​</a></h2><h2 id="一路追随-be-first-的《rockin-on-japan》献上从过去到现在的足球长传式访谈" tabindex="-1">一路追随 BE:FIRST 的《ROCKIN&#39;ON JAPAN》献上从过去到现在的足球长传式访谈 <a class="header-anchor" href="#一路追随-be-first-的《rockin-on-japan》献上从过去到现在的足球长传式访谈" aria-label="Permalink to &quot;一路追随 BE:FIRST 的《ROCKIN&#39;ON JAPAN》献上从过去到现在的足球长传式访谈&quot;">​</a></h2><p>2021 年，从选秀企划《THE FIRST》诞生的 BE:FIRST，于 11 月 3 日迎来主流出道 4 周年。就在此前的 10 月 29 日，他们发行了组合首张精选专辑《BE:ST》。4 年就出精选专辑这件事，放在一般艺人身上，或许会显得有些早；但当你看到曲目表里排开的 30 多首作品，就会明白BE:FIRST的这一步是顺理成章的。刻在这张专辑里的多彩与多样，正是他们高密度岁月的足迹，也是进化的证明。</p><p>4 年前，BE:FIRST 在事务所社长兼制作人 SKY-HI 的引导下起步；如今，他们带着健康的自由度和贪婪的好奇心，正靠自己的脚步不断跃上新的台阶。从巨蛋巡演到世界巡演，再到体育场公演，演出规模持续扩张，这就是最直接的证据。更重要的是，在这背后是成员们主动、深度参与歌曲制作，亲自捕捉「当下需要的声音」并将他们做成音乐。《BE:1》的主打曲《Scream》中有一句歌词——「最高が何なのか証明しよう（来证明什么是顶级吧）」。而他们也正如这句宣言所说，持续更新并证明自己的「顶级」，一直到现在。</p><p>在《BE:ST》这个节点策划 BE:FIRST 特集时，我们最想做的一件事，就是揭开这耀眼历史背后每一位成员当时究竟在想什么。</p><p>作为最强进化集团 BE:FIRST 而前行，他们到底改变了什么，又是如何一路保持不变的——其实在《ROCKIN&#39;ON JAPAN》，从《BE:1》发行后的 2022 年秋天起，我们就用约半年时间，进行了成员个人采访连载。这次别册特集中，我们一边摘录他们当时各自说过的话，一边尝试做一次访谈，再次触碰他们底层信念的流向（另外，各采访页面也重新刊载了 3 年前报道中的旧照片，也请关注他们在这些画面里的变化）。</p><p>为什么 BE:FIRST 会是 BE:FIRST？为什么他们能持续证明自己是「顶级」？</p><p>我认为，这是一组能够触及其真髓、独一无二的特集。 <br><br></p><p>（安田季那子）</p><p>采访＝小川智宏　摄影＝大野隼男</p><hr>',11)])])}const I=e(p,[["render",s]]);export{u as __pageData,I as default};
